import { MakeLogicType, connect, kea, path, selectors } from 'kea'

import { userLogic } from 'scenes/userLogic'

import { PendingInviteForCurrentUser } from '~/types'

import type { UserType } from '../../../types'

export type { PendingInviteForCurrentUser }

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pendingInvitesLogicValues {
    user: UserType | null // userLogic
    pendingInvites: PendingInviteForCurrentUser[]
    pendingInvitesLabel: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pendingInvitesLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        pendingInvites: (user: UserType | null) => PendingInviteForCurrentUser[]
        pendingInvitesLabel: (pendingInvites: PendingInviteForCurrentUser[]) => string | null
    }
}

export type pendingInvitesLogicType = MakeLogicType<
    pendingInvitesLogicValues,
    {},
    Record<string, any>,
    pendingInvitesLogicMeta
>

export const pendingInvitesLogic = kea<pendingInvitesLogicType>([
    path(['lib', 'components', 'Account', 'pendingInvitesLogic']),
    connect(() => ({
        values: [userLogic, ['user']],
    })),
    selectors({
        pendingInvites: [
            (s) => [s.user],
            (user: null | import('~/types').UserType): PendingInviteForCurrentUser[] => user?.pending_invites ?? [],
        ],
        pendingInvitesLabel: [
            (s) => [s.pendingInvites],
            (pendingInvites: PendingInviteForCurrentUser[]): string | null => {
                if (pendingInvites.length === 0) {
                    return null
                }
                if (pendingInvites.length === 1) {
                    return `Pending invite to ${pendingInvites[0].organization_name}`
                }
                return `${pendingInvites.length} pending invites to other organizations`
            },
        ],
    }),
])
